algorithms.pseudocode:
function radical(n):
    result <- 1; d <- 2
    while d*d <= n:
        if d | n: result <- result * d
            while d | n: n <- n/d
        d <- d + 1
    if n > 1: result <- result * n
    return result

function abc_quality(a, b, c):
    r <- radical(a * b * c)
    return log(c) / log(r)

function exceeds_discrete_quality(m, a, b, c):
    return c^m > radical(a*b*c)^(m+1)

Complexity: O(sqrt(n)) per radical computation
